// What WhatsApp and the networks show when a page has no cover of its own
// (step 8.8): generated by src/app/og/route.tsx. Relative: metadataBase
// (the root layout) turns it into a full address.
export const DEFAULT_OG_IMAGE = {
  url: "/og",
  width: 1200,
  height: 630,
  alt: "Reconstruyendo Esperanza · Calarcá, Quindío",
};

/** The page's cover for sharing, or the default image. */
export function ogImages(
  cover: { large: string; width: number; height: number; alt: string } | null,
) {
  if (!cover) return [DEFAULT_OG_IMAGE];
  const width = Math.min(cover.width, 1920);
  return [
    {
      url: cover.large,
      width,
      height: Math.round((width / cover.width) * cover.height),
      alt: cover.alt,
    },
  ];
}
